<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {request,failure,paginated} from '../Administration/api';
import {registrationDate} from '../FleetAndDocuments/presentation';
import {labels as stateLabels} from '../TransportAndDispatch/presentation';
interface Trip {id:string;product:string;execution_status:string;administrative_status:string;scheduled_start_at:string|null;route:{name:string;origin:string;destination:string};assets:{type:string;code:string}[]}
const emit=defineEmits<{denied:[error:unknown]}>();
const trips=ref<Trip[]>([]),loading=ref(false),error=ref(''),page=ref(1),last=ref(1);let generation=0;
async function load(target=page.value):Promise<void>{if(loading.value)return;const current=++generation;loading.value=true;error.value='';try{const result=await paginated<Trip>(`/transport/my-trips?page=${target}`);if(current!==generation)return;trips.value=result.data;page.value=result.meta.current_page;last.value=result.meta.last_page;}catch(e){if(current!==generation)return;error.value=failure(e).message;if([401,403].includes(failure(e).status)){trips.value=[];emit('denied',e);}}finally{if(current===generation)loading.value=false;}}
onMounted(()=>load());onBeforeUnmount(()=>generation++);
</script>
<template><section class="space-y-4"><h2 class="text-xl font-semibold">Mis viajes asignados</h2><p class="text-sm">Asignaciones vigentes. Finalizar o cancelar un viaje no libera sus recursos automáticamente.</p><p v-if="error" role="alert" class="notice-error">{{error}}</p><button class="btn-secondary" :disabled="loading" @click="load()">Actualizar viajes</button><p v-if="loading" role="status">Consultando viajes…</p><p v-else-if="!trips.length">No hay viajes asignados vigentes.</p><article v-for="trip in trips" :key="trip.id" class="panel space-y-2"><h3 class="font-semibold">{{trip.route.name}} · {{trip.product}}</h3><p>{{trip.route.origin}} → {{trip.route.destination}}</p><p>Viaje {{trip.id}}</p><p>{{stateLabels[trip.execution_status]??trip.execution_status}} · {{stateLabels[trip.administrative_status]??trip.administrative_status}}</p><p>Programación: {{trip.scheduled_start_at?registrationDate(trip.scheduled_start_at):'Sin fecha registrada'}}</p><p v-for="asset in trip.assets" :key="asset.code">{{asset.type==='tanker'?'Cisterna':'Cabezal'}}: {{asset.code}}</p></article><div class="flex gap-3"><button class="btn-secondary" :disabled="loading||page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="loading||page>=last" @click="load(page+1)">Siguiente</button></div><p class="text-sm text-slate-600">Consulta en línea. La PWA y el trabajo offline no están implementados.</p></section></template>
